long modp(long x){return (x%psmall+psmall)%psmall;}
long power_small(long x,long n,long m){long r=1;while(n){if(n&1)r=r*x%m;x=x*x%m;n>>=1;}return r;}
F random_field(){std::vector<Z> c;for(int i=0;i<modulus.degree();++i)c.emplace_back(long(random_word()%uint64_t(psmall)));return F(Poly<Z>(c));}
