    int weight()const{int n=0;for(auto&g:lifts)n+=g.exponent;return n;}
    void rebuild(){coordinates.clear();std::vector<std::pair<D,std::vector<int>>> rows{{D{},std::vector<int>(lifts.size())}};for(size_t i=0;i<lifts.size();++i){auto old=rows;for(auto row:old){row.first=row.first.add(lifts[i].top);row.second[i]=1;rows.push_back(row);row.first=row.first.add(lifts[i].top);row.second[i]=2;rows.push_back(row);}}for(auto&row:rows)require(coordinates.emplace(row.first.key(),row.second).second,"toy independent3-primary tops");require(weight()<=valuation&&lifts.size()<=4,"toy Sylow size/rank");}
