std::vector<int> f3remainder(std::vector<int>a,const std::vector<int>&f){while(!a.empty()&&a.back()==0)a.pop_back();while(a.size()>=f.size()){int z=a.back()*f.back()%3;size_t shift=a.size()-f.size();for(size_t i=0;i<f.size();++i)a[shift+i]=m3(a[shift+i]-z*f[i]);while(!a.empty()&&a.back()==0)a.pop_back();}return a;}
std::vector<int> f3multiply(const std::vector<int>&a,const std::vector<int>&b,const std::vector<int>&f){std::vector<int> c(a.size()+b.size());for(size_t i=0;i<a.size();++i)for(size_t j=0;j<b.size();++j)c[i+j]=(c[i+j]+a[i]*b[j])%3;return f3remainder(c,f);}
int semisimple_degree(long t,long c){std::vector<int> f{m3(int(psmall*psmall)),m3(int(-psmall*t)),m3(int(c)),m3(int(-t)),1},x{0,1},pow{1};for(int m=1;m<=80;++m){pow=f3multiply(pow,x,f);if(m%3==0)continue;auto a=pow;if(a.empty())a.push_back(0);a[0]=m3(a[0]-1);auto sq=f3multiply(a,a,f);if(f3multiply(sq,sq,f).empty())return m;}throw std::runtime_error("toy semisimple order bound");}
struct Tangent {P cubic;F lambda;};
