std::optional<F> pairing(const D&a,const Tangent&ta,const D&b,const Tangent&tb){F n=result(b.u,b.v-ta.cubic),d=result(a.u,a.v-tb.cubic);if(n==F(0)||d==F(0))return {};F e=n/d*ta.lambda/tb.lambda;require(e.power(3)==F(1),"toy Weil value");return e;}
