    bool insert(std::vector<long> a,long rhs){require(int(a.size())==cols,"toy matrix width");for(auto&x:a)x=(x%r+r)%r;a.push_back((rhs%r+r)%r);for(size_t i=0;i<rows.size();++i){long z=a[pivots[i]];for(int k=0;k<=cols;++k)a[k]=(a[k]-z*rows[i][k]%r+r)%r;}int pivot=0;while(pivot<cols&&a[pivot]==0)++pivot;if(pivot==cols){require(a[cols]==0,"toy inconsistent relation matrix");return false;}long inv=inverse_small(a[pivot],r);for(auto&x:a)x=x*inv%r;for(auto&row:rows){long z=row[pivot];for(int k=0;k<=cols;++k)row[k]=(row[k]-z*a[k]%r+r)%r;}auto pos=std::lower_bound(pivots.begin(),pivots.end(),pivot)-pivots.begin();pivots.insert(pivots.begin()+pos,pivot);rows.insert(rows.begin()+pos,a);return true;}
